    {
      "card_ids": ["C24"],
      "claim": "Verapamil, which shares the dimethoxyphenethylamine and N-methylaminoalkyl motif, has low oral bioavailability of about 18–20% in normal subjects due to extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Noscapine, a dimethoxy-substituted isoquinoline alkaloid, has an absolute oral bioavailability of about 30% in humans, with wide interindividual variation.",
